import random, math
from app.api.handlers import handle_calc

random.seed(1)
def gen(depth=0):
    if depth > 2 or random.random() < 0.4:
        return str(random.randint(0, 20))
    r = random.random()
    if r < 0.25:
        return "(" + gen(depth+1) + ")"
    if r < 0.4:
        return "-" + gen(depth+1)
    op = random.choice("+-*/")
    return gen(depth+1) + op + gen(depth+1)

mismatch = 0
checked = 0
for _ in range(20000):
    e = gen()
    if len(e) > 100:
        continue
    try:
        ref = eval(e)
    except ZeroDivisionError:
        ref = "DIVZERO"
    except Exception:
        ref = "INVALID"
    got = handle_calc({"expr": e})
    checked += 1
    if ref == "DIVZERO":
        exp = (400, {"error": "division by zero"})
    elif ref == "INVALID":
        exp = (400, {"error": "invalid expression"})
    else:
        # whole -> int, else float
        exp = (200, {"result": ref})
    if got != exp:
        mismatch += 1
        if mismatch < 20:
            print("MISMATCH", repr(e), "got", got, "ref", ref)
print("checked", checked, "mismatches", mismatch)
EOF
